// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.List;
import java.util.concurrent.atomic.AtomicLong;

import org.junit.jupiter.api.Test;

class LmdbNativeProbeSchedulerTest {

	private static final LmdbNativeProbeConfig CONFIG = LmdbNativeProbeConfig.defaults();
	private static final LmdbNativeRegimeKey REGIME = LmdbNativeRegimeKey.STEADY;

	private static LmdbNativePhysicalVariantKey variant(String family) {
		return LmdbNativePhysicalVariantKey.builder(family).build();
	}

	@Test
	void oneCensoringFulfillsTheObligationAndStartsAnExponentialCooldown() {
		AtomicLong wall = new AtomicLong(1_000_000L);
		LmdbNativeProbeScheduler scheduler = new LmdbNativeProbeScheduler(CONFIG, wall::get);
		LmdbNativePhysicalVariantKey arm = variant("nestedLoop");

		assertTrue(scheduler.mayProbe(arm, REGIME, 0L), "an unknown arm is probe-eligible");
		scheduler.censored(arm, REGIME, 0L, false);
		assertFalse(scheduler.mayProbe(arm, REGIME, 0L), "one timeout means no immediate re-probe");
		assertEquals(LmdbNativeProbeScheduler.State.COOLDOWN, scheduler.state(arm, REGIME, 0L));

		wall.addAndGet(CONFIG.cooldownBaseMillis() + 1L);
		assertTrue(scheduler.mayProbe(arm, REGIME, 0L), "the first cooldown expires after the base interval");
	}

	@Test
	void aSecondSameEpochCensoringParksTheArmUntilTheNextEpoch() {
		AtomicLong wall = new AtomicLong(1_000_000L);
		LmdbNativeProbeScheduler scheduler = new LmdbNativeProbeScheduler(CONFIG, wall::get);
		LmdbNativePhysicalVariantKey arm = variant("wcoj");

		scheduler.censored(arm, REGIME, 7L, false);
		wall.addAndGet(CONFIG.cooldownBaseMillis() + 1L);
		scheduler.censored(arm, REGIME, 7L, false);
		assertEquals(LmdbNativeProbeScheduler.State.DORMANT_UNTIL_EPOCH, scheduler.state(arm, REGIME, 7L));
		wall.addAndGet(365L * 24 * 3_600_000L);
		assertFalse(scheduler.mayProbe(arm, REGIME, 7L), "dormancy never expires by wall clock");
		assertTrue(scheduler.mayProbe(arm, REGIME, 8L), "an epoch bump revives the arm");
	}

	@Test
	void aSevereMissQuarantinesAndAnEpochBumpRevives() {
		AtomicLong wall = new AtomicLong(1_000_000L);
		LmdbNativeProbeScheduler scheduler = new LmdbNativeProbeScheduler(CONFIG, wall::get);
		LmdbNativePhysicalVariantKey arm = variant("irKernel");

		scheduler.censored(arm, REGIME, 3L, true);
		assertTrue(scheduler.quarantined(arm, REGIME, 3L), "a censor above the settled 99% bound quarantines");
		assertFalse(scheduler.mayProbe(arm, REGIME, 3L));
		assertFalse(scheduler.quarantined(arm, REGIME, 4L), "quarantine is epoch-scoped");
		wall.addAndGet(CONFIG.cooldownBaseMillis() * 10L + 1L);
		assertFalse(scheduler.quarantined(arm, REGIME, 3L), "quarantine also expires by wall clock");
	}

	@Test
	void goodCompletionsClearStrikesAndRegimesAreIndependent() {
		AtomicLong wall = new AtomicLong(1_000_000L);
		LmdbNativeProbeScheduler scheduler = new LmdbNativeProbeScheduler(CONFIG, wall::get);
		LmdbNativePhysicalVariantKey arm = variant("factorized");
		LmdbNativeRegimeKey building = new LmdbNativeRegimeKey(LmdbNativeRegimeKey.Phase.BUILDING, 0L, false, 0L);

		scheduler.censored(arm, REGIME, 0L, false);
		assertFalse(scheduler.mayProbe(arm, REGIME, 0L));
		assertTrue(scheduler.mayProbe(arm, building, 0L), "a cooldown in one regime does not leak into another");

		wall.addAndGet(CONFIG.cooldownBaseMillis() + 1L);
		scheduler.completed(arm, REGIME, 0L, false);
		assertEquals(LmdbNativeProbeScheduler.State.ACTIVE, scheduler.state(arm, REGIME, 0L));
		scheduler.censored(arm, REGIME, 0L, false);
		assertEquals(LmdbNativeProbeScheduler.State.COOLDOWN, scheduler.state(arm, REGIME, 0L),
				"a good completion reset the strike count — this is the FIRST strike again, not dormancy");
	}

	@Test
	void cooldownSnapshotRoundTripsAndDropsExpiredEntries() {
		AtomicLong wall = new AtomicLong(1_000_000L);
		LmdbNativeProbeScheduler scheduler = new LmdbNativeProbeScheduler(CONFIG, wall::get);
		LmdbNativePhysicalVariantKey cooled = variant("cooled");
		LmdbNativePhysicalVariantKey dormant = variant("dormant");
		scheduler.censored(cooled, REGIME, 2L, false);
		scheduler.censored(dormant, REGIME, 2L, false);
		scheduler.censored(dormant, REGIME, 2L, false);

		List<LmdbNativeProbeScheduler.CooldownEntry> snapshot = scheduler.snapshotCooldowns();
		assertEquals(2, snapshot.size());

		LmdbNativeProbeScheduler restoredScheduler = new LmdbNativeProbeScheduler(CONFIG, wall::get);
		restoredScheduler.restoreCooldowns(snapshot, wall.get());
		assertFalse(restoredScheduler.mayProbe(cooled, REGIME, 2L), "a live cooldown survives the restart");
		assertFalse(restoredScheduler.mayProbe(dormant, REGIME, 2L), "dormancy survives the restart");

		LmdbNativeProbeScheduler lateScheduler = new LmdbNativeProbeScheduler(CONFIG, wall::get);
		lateScheduler.restoreCooldowns(snapshot, wall.get() + CONFIG.cooldownBaseMillis() * 100L);
		assertTrue(lateScheduler.mayProbe(cooled, REGIME, 2L), "an expired cooldown is dropped at restore");
		assertFalse(lateScheduler.mayProbe(dormant, REGIME, 2L), "dormancy is epoch-bound, not wall-clock-bound");
	}
}
